# ================================================================== PART 3 · THE COMMAND
flow(id="rules", part=2, scope="world",
 title="Where the Rules Are Written",
 kick="The rules for the world's banks, markets and accounts are drafted by committees in a few cities. Some are public bodies with no legal power. Some are private associations of the firms being ruled.",
 sum="Parts 1 and 2 described a machine. From here the map asks who is in charge of it, starting at the top. Above every national regulator in Chapter 4 sits a layer of international bodies that write the standards those regulators adopt. No parliament elects them, and most people have never heard their names.<br><br>They are of two kinds. The first is committees of public officials: central bankers and regulators who meet, mostly in the Swiss city of Basel, and agree rules they then take home. The second is private bodies: a foundation that writes the accounting rules most of the world must use, and a trade association of banks and funds that wrote the contract under which the world's derivatives are made.<br><br>I am not suggesting these bodies meet in secret; their papers are published. What matters is the order of events. A rule is negotiated among officials and the largest firms first. It reaches a national parliament afterwards, already agreed, with a warning that changing it would put the country out of step with everyone else.",
 bridge="The four slides go from public to private. The first is the committee in Basel that sets how much capital a bank needs. The second is the cluster of sister bodies around it. The third is the private foundation that defines what profit means. The fourth is the trade association whose contract governs derivatives.",
 out="The rulebook is written by committees of officials and by private bodies of the regulated, before any parliament votes. The next chapter turns to the firms that grade everyone else.",
 rec="International committees and private associations write the rules; national regulators and parliaments adopt them afterwards.",
 roles=["Where the rule-writing body sits"],
 src=[S("Basel Committee on Banking Supervision, charter", BCBSU), S("IFRS Foundation, use of IFRS standards by jurisdiction", IFRSU),
      S("International Swaps and Derivatives Association, About ISDA", ISDAU), S("Bank for International Settlements, OTC derivatives statistics at end-June 2025", OTC)],
 steps=[
  st("Today", "Basel", BASEL, 3.6, "Basel: A Committee With No Legal Power",
   "Chapter 4 ended with the rule that a bank must hold a minimum of capital. The body that sets the world's minimum is the Basel Committee on Banking Supervision. Its members are central banks and bank supervisors. Its own charter says it has no formal authority above nations and that its decisions do not have legal force. Yet its standards, known as Basel I, II and III, are the banking law of nearly every country, because members commit to adopt them and other countries follow so that their banks are accepted abroad. The committee lets large banks measure the riskiness of their own loans with their own models, and the capital they must hold depends on the answer. A bank that judges its loans safe needs less capital, and Chapter 4 showed why its owners want less.",
   BCBSU, pl=["bcbs"], ex=["bcbs_charter"], add={"Switzerland": 0}),
  st("Today", "Basel, Madrid, Paris", [3, 46], 3.4, "The Sister Bodies",
   "Around the Basel Committee is a family of similar bodies. The Financial Stability Board coordinates them and names the banks too large to fail. A committee on payments sets the standards for the pipes of Chapters 5 and 6. An association of insurance supervisors does the same for insurers. All four are housed in the same tower in Basel, at the Bank for International Settlements. In Madrid, an organisation of securities commissions sets standards for markets. In Paris, a task force of governments sets the checks banks must run on their customers, and lists countries that fall short; a country on that list finds foreign banks closing its accounts. The largest firms have their own voice in each discussion through lobby groups such as the Institute of International Finance in Washington.",
   BCBSU, pl=["bcbs", "fsb", "cpmi", "iais", "iadi", "iosco", "fatf", "iif"], arcs=[[BASEL, MADRID], [BASEL, PARIS]], an=[["Basel", "Madrid"], ["Basel", "Paris"]], add={"Switzerland": 0, "Spain": 0, "France": 0}),
  st("Today", "London", LONDON, 3.6, "A Private Foundation Defines Profit",
   "Whether a bank has enough capital, whether a company made a profit, what a pension fund owes: each is a number in a set of accounts, and the number depends on the accounting rules. Those rules are written by a private body. The IFRS Foundation, a non-profit registered in the United States and based in London, appoints the board that writes International Financial Reporting Standards. The foundation says companies in more than 140 jurisdictions are required to use them. The United States has its own private board. A change in one of these rules, such as when a bank must admit that a loan has gone bad, can move billions between this year's profit and next year's without anything in the world changing. The firms most affected, the banks and the four large audit networks, supply much of the expertise and many of the people.",
   IFRSU, pl=["ifrs", "fasb", "deloitte", "pwc", "ey", "kpmg"], ex=["ifrs140"], add={"United Kingdom": 0}),
  st("June 2025", "New York", NY, 3.2, "A Trade Association Wrote the Contract",
   "A derivative is a contract whose value depends on something else: an interest rate, a currency, whether a company fails. Most are private deals between two firms and never pass through an exchange. In June 2025 the Bank for International Settlements put the face value of such contracts at 846 trillion dollars. Nearly all are made under one standard contract, the Master Agreement, written by the International Swaps and Derivatives Association, a trade association with more than 1,000 member firms from 79 countries. The same association runs the committees of dealers and investors that rule on whether a borrower has defaulted in a way that triggers payment on credit derivatives. So the firms that trade these contracts wrote their terms and judge their disputes. A national court sees a case only after that.",
   OTC, pl=["isda"], ex=["isda_about"], add={"United States": 0}),
 ])

flow(id="graders", part=2, scope="world",
 title="The Graders",
 kick="Three rating agencies, four audit networks and a handful of index makers decide what counts as safe, what the accounts say and where savings must go. The firms they judge pay them.",
 sum="The rule-writers decide what is allowed. A second group decides what is believed. Chapter 3 introduced them in a single slide. They get a chapter here because so much of the system has been wired to follow their word without further thought.<br><br>A pension fund's rulebook says it may only buy bonds rated above a certain grade. The Basel rules let a bank hold less capital against a highly rated bond. An index fund must buy whatever is on the index and nothing else. In each case a private company's opinion has been turned into something close to an instruction, and trillions of dollars move when it changes.<br><br>None of these firms takes deposits or lends. They hold almost no risk themselves. Their power comes from being few, and from being written into other people's rules.",
 bridge="The three slides take the graders in turn. The first counts the rating agencies' share and explains who pays them. The second does the same for the auditors. The third explains how index makers came to direct a growing share of the world's savings.",
 out="A few private firms grade the borrowers, check the books and write the shopping lists, and the firms they judge are their customers. Next, the pipes themselves.",
 rec="Three rating agencies, four audit networks and a few index makers hold the power to grade, and are paid by those they grade.",
 roles=["Where the grading firms are based"],
 src=[S("US Securities and Exchange Commission, staff report on nationally recognized statistical rating organizations (January 2025)", SECR),
      S("Wikipedia, Big Four accounting firms", BIG4), S("Thinking Ahead Institute, The world's largest 500 asset managers (2025)", TAIU)],
 steps=[
  st("End of 2023", "New York", NY, 3.2, "Three Agencies, 94 Per Cent of All Ratings",
   "The United States markets regulator registers rating agencies and reports on them every year. Its staff report of January 2025 counted 2,113,208 ratings outstanding at the end of 2023. S&P had issued 49.96 per cent, Moody's 31.73 per cent and Fitch 12.46 per cent: 94.15 per cent between three firms. They earned 91.9 per cent of the industry's revenue. Until the 1970s investors paid for ratings. Since then the borrower pays. A bank that builds a bond out of mortgages can show it to more than one agency and hire the one that offers the best grade. Before 2008 thousands of mortgage bonds were rated AAA, the grade given to the safest governments, and lost most of their value within two years. The same three firms still rate nearly everything, including the debts of countries, whose cost of borrowing moves when the grade does.",
   SECR, pl=["sp", "moodys", "fitch", "dbrs", "jcr", "dagong"], ex=["sec_nrsro"], add={"United States": 0}),
  st("2011 to 2019", "London", LONDON, 3.6, "Four Networks Check Nearly Every Large Company",
   "An auditor is hired to check that a company's accounts are true. Four networks do this for almost all large companies: Deloitte, PwC, EY and KPMG. In Britain they audited 99 per cent of the hundred largest listed companies in 2011, and 95 per cent of the next 250 in 2019. There were eight such firms in the 1980s; mergers and one collapse, Arthur Andersen after the Enron fraud of 2001, left four. The company being audited chooses its auditor and pays the fee, and the same networks sell that company tax and consulting advice worth more than the audit. Every large bank that failed or was rescued in 2008 had a clean audit opinion from one of the four months earlier. With only four, a regulator cannot close one down without leaving large companies with nobody to audit them, and all four know that.",
   BIG4, pl=["deloitte", "pwc", "ey", "kpmg"], ex=["big4"], add={"United Kingdom": 0, "Netherlands": 0}),
  st("End of 2024", "New York", NY, 3.2, "The Index Makers Write the Shopping List",
   "An index is a list of securities with a weight for each. An index fund holds exactly that list. At the end of 2024, 39 per cent of the money run by the 500 largest asset managers was invested this way, without anyone choosing what to buy. The choosing is done once, by the index maker. Three firms dominate: MSCI, S&P Dow Jones Indices and FTSE Russell, which belongs to the London Stock Exchange Group. When MSCI decides that a country moves from its emerging to its frontier list, or that a company's shares no longer qualify, funds that follow its lists must sell, and the price falls whether or not anything changed in the country or the company. Governments now lobby index makers the way they once courted banks. The index makers are paid a licence fee by the funds for each list.",
   TAIU, pl=["msci", "sp", "lseg", "bloomberg", "blackrock", "vanguard", "statestreet"], ex=["tai2025"], add={"United States": 0}),
 ])

flow(id="pipes", part=2, scope="world",
 title="The Pipes Have Owners",
 kick="Each pipe in Part 2 is run by one or two organisations. Most belong to the largest banks or to exchange companies, and whoever runs a pipe can shut someone out of it.",
 sum="Chapters 5 and 6 treated the pipes as if they were public roads. They are not. The message network, the dollar clearing system, the clearing houses, the depositories and the card networks each belong to someone, and in nearly every case there are only one or two to choose from.<br><br>That matters in three ways. An owner sets the price of using the pipe. An owner writes its rulebook, including what happens to your trade or your collateral in a crisis. And an owner, or the government with power over that owner, can disconnect a bank or a whole country. All three have happened.<br><br>The chapter ends with systems built in the last decade by China, Russia, India and Brazil. I include them because they show that the pipes are a design choice. Two of them were built to escape exclusion from the existing ones. Two were built by central banks as public services and are free to the people who use them.",
 bridge="The six slides go pipe by pipe. The first is the message network and its power to disconnect. The second is the dollar's own pipes. The third is the clearing houses. The fourth is a case in which a market cancelled its customers' trades. The fifth is the depositories. The sixth maps the alternatives.",
 out="The pipes are few, privately owned or governed from a handful of capitals, and can be closed to a bank or a country. The next chapter looks at the firms at the centre of them all.",
 rec="Each payment and settlement pipe has one or two owners, who set its price and rules and can shut users out.",
 roles=["Where the pipe is run from", "Cut off from a pipe by sanctions", "Built its own system"],
 src=[S("Swift, Who we are", SWIFTW), S("Wikipedia, SWIFT (oversight and sanctions)", SWIFTWIKI), S("LCH, SwapClear volumes", LCHU),
      S("US Financial Stability Oversight Council, designations", FSOC), S("Wikipedia, London Metal Exchange", LMEW), S("Wikipedia, Euroclear", EUROW),
      S("Wikipedia, Cross-Border Interbank Payment System", CIPSW), S("Wikipedia, SPFS", SPFSW), S("Wikipedia, Unified Payments Interface", UPIW), S("Wikipedia, Pix (payment system)", PIXW)],
 steps=[
  st("1973 to 2022", "La Hulpe, Belgium", LAHULPE, 3.4, "The Message Network, and the Power to Disconnect",
   "Swift is a cooperative founded in 1973 and owned by its member banks, with its headquarters in La Hulpe, near Brussels. More than 11,500 institutions use it, and in 2025 it carried an average of 59.8 million payment messages a day. Shares in it are handed out according to how much each member uses it, so the largest banks hold the most. It is overseen by the central banks of ten rich countries, led by Belgium's. Swift is subject to Belgian and European law. In 2012, after a European Union regulation, it disconnected Iranian banks under sanctions. In March 2022 it disconnected seven Russian banks. A disconnected bank can still hold money. It cannot easily tell any bank abroad what to do with it, so trade with that country slows to what can be arranged by other means.",
   SWIFTW, pl=["swift"], ex=["swift_sanctions"], add={"Belgium": 0, "Iran": 1, "Russia": 1}, arcs=[[LAHULPE, [51.389, 35.6892]], [LAHULPE, MOSCOW]], an=[["La Hulpe", "Tehran"], ["La Hulpe", "Moscow"]]),
  st("2025", "New York", NY, 3.2, "The Dollar's Own Pipes",
   "Chapter 5 showed a payment from Nairobi to Bangkok settling in New York. Two systems do that work. Fedwire belongs to the Federal Reserve. CHIPS belongs to The Clearing House, a company owned by large commercial banks, and it handles more than 2 trillion dollars a day. A foreign bank reaches either one only through an American bank or branch that agrees to act for it. Since nearly nine in ten currency trades have the dollar on one side, almost every bank in the world needs such a relationship, and the United States government can fine or prosecute the American bank for what passes through. The effect is that a law passed in Washington applies to a payment between two companies that have never been to the United States. The banks in the middle earn a fee on each payment and hold the balances overnight.",
   CHIPSU, pl=["tch", "fedwire", "jpm", "citi", "bny", "bofa", "wfc", "hsbc", "deutsche", "stanchart"], add={"United States": 0}),
  st("Today", "London and Chicago", [-40, 46], 2.1, "Clearing Houses: Required by Law, Owned for Profit",
   "After 2008, governments required standard derivatives to pass through clearing houses. That turned a few firms into compulsory middlemen. LCH in London, majority-owned by the London Stock Exchange Group, says it handles roughly 90 per cent of the cleared market in interest rate swaps and regularly clears more than 9 trillion dollars a day. Most other large clearing houses belong to exchange companies listed on the stock market: CME, Intercontinental Exchange, Deutsche Börse, Hong Kong Exchanges. The United States has designated eight market utilities as so important that their failure could threaten the financial system; five of them are clearing houses. A clearing house earns fees on volume. The cushion against a member's failure is mostly the other members' money, and only a thin slice is its owners'. Its owners keep the profit in good years.",
   LCHU, pl=["lch", "lchsa", "cme", "iceclearcredit", "iceclear", "eurexclearing", "occ", "jscc", "shch", "ccil", "nasdaqclearing", "cboeclear", "kdpwccp", "euronextclearing", "ecc", "bmeclearing", "cdcc", "lseg", "ice", "dboerse", "hkex"], ex=["lch_share", "fsoc8"], arcs=[[CHICAGO, LONDON]], an=[["Chicago", "London"]], add={"United Kingdom": 0, "United States": 0},
   note="The ringed circles are every clearing house in the directory and the four exchange groups named in the text. The directory includes the clearing houses on the European Union's list of authorised central counterparties that I could place, and the main ones elsewhere; it is not a complete world list."),
  st("8 March 2022", "London", LONDON, 3.6, "Regional Example: The Day a Market Cancelled Its Trades",
   "Regional Example: the London Metal Exchange and nickel, 2022. The London Metal Exchange is the main market for industrial metals and belongs to Hong Kong Exchanges and Clearing. On 8 March 2022 the price of nickel more than doubled within hours, as a large producer that had bet on a fall was caught out. The exchange suspended the market and then cancelled the trades already made that morning. Traders on the winning side lost their gains; the firms on the losing side, and the clearing house that would have had to collect from them, were spared. Two trading firms sued for 456 million and 15.3 million dollars and lost in the High Court in November 2023. In March 2025 the British regulator fined the exchange 9.2 million pounds for its controls. The rulebook that allowed the cancellation was the exchange's own.",
   LMEW, reg=True, pl=["lme", "hkex", "fca"], ex=["lme_nickel"], add={"United Kingdom": 0}),
  st("Since February 2022", "Brussels and Luxembourg", [5.2, 50.2], 5.6, "The Depositories: Where the Record Is Kept",
   "Chapter 6 showed that owning a security means having a line in a depository's records. Each country has one. For bonds sold across borders the world has two: Euroclear in Brussels and Clearstream in Luxembourg, which belongs to Deutsche Börse. Whoever has legal power over the depository has power over the line. When Western governments froze the Bank of Russia's reserves in February 2022, they did not need to find anything. Most of those reserves were bonds recorded at Euroclear, and an order to Euroclear was enough. Whatever one thinks of that decision, every central bank and state fund in the world watched it. An asset held through this system is held at the pleasure of the governments of Belgium, Luxembourg and the United States, where the largest depository of all, DTCC, sits.",
   EUROW, pl=["euroclear", "clearstream", "dtcc", "nsdru", "dboerse"], ex=["euroclear_ru"], arcs=[[BRUSSELS, LUX]], an=[["Brussels", "Luxembourg"]], add={"Belgium": 0, "Luxembourg": 0, "Russia": 1}),
  st("2015 to 2026", "Shanghai, Moscow, Mumbai, Brasília", [40, 15], 1.5, "Other Pipes Exist",
   "Four countries have built their own. China opened a system for cross-border payments in yuan in 2015; by June 2025 it had 176 direct participants and 1,514 indirect ones, 1,102 of them in Asia. Russia built a messaging system as a substitute for Swift; in January 2024 its central bank counted 550 users, 150 of them from 16 other countries. Both exist so that their owners cannot be cut off. India and Brazil did something different. India's UPI, run by a non-profit company set up by the central bank and the banks, carried 241.62 billion payments in the year to March 2026. Brazil's Pix, built by its central bank in 2020, has about 200 million monthly users, and within three years carried more payments than cards. Both are instant and free to individuals. In those two countries the 2 per cent from Chapter 5 is no longer charged on most everyday payments.",
   CIPSW, pl=["cips", "spfs", "npci", "pix"], ex=["altpipes"], add={"China": 2, "Russia": 2, "India": 2, "Brazil": 2}, pins=[[SHANGHAI[0], SHANGHAI[1], "CIPS, Shanghai"], [MOSCOW[0], MOSCOW[1], "SPFS, Moscow"], [MUMBAI[0], MUMBAI[1], "UPI, Mumbai"], [BRASILIA[0], BRASILIA[1], "Pix, Brasília"]]),
 ])

flow(id="core", part=2, scope="world",
 title="The Few Dozen Firms at the Centre",
 kick="Count the names that appeared in the last eleven chapters. The same few dozen firms take the deposits, sell the securities, hold them, manage them and own the pipes.",
 sum="Part 1 listed a dozen kinds of institution as if each were a separate trade. In practice the largest firms are several of them at once. One American bank is a high-street bank, an investment bank, one of the four big custodians, the fifth-largest asset manager, a main dollar correspondent for foreign banks, a part-owner of CHIPS and of the depository, and a member of every large clearing house.<br><br>This chapter counts how few firms sit at the centre. It uses official lists and published rankings and nothing else: the 29 banks the Financial Stability Board names as too large to fail, the World Bank's measure of how much of each country's banking its five largest banks hold, and the ranking of asset managers.<br><br>The website this map belongs to deals elsewhere with how these firms own shares in one another. I leave that out. Here the point is narrower. A system with this few firms at its centre cannot let any of them fail, and every one of them knows it.",
 bridge="The four slides narrow in. The first draws all 29 designated banks. The second shades every country by the share of banking its five largest banks hold. The third counts the asset managers. The fourth shows one firm in every role.",
 out="Twenty-nine banks, four custodians, three raters, four auditors, twenty asset managers and one or two owners per pipe. Part 4 asks what this arrangement costs.",
 rec="A few dozen firms, many of them doing several jobs at once, sit at the centre of every flow in the system.",
 roles=["Home of one or more of the 29 designated banks"],
 src=[S("Financial Stability Board, 2025 list of global systemically important banks", GSIB), S("World Bank, Global Financial Development Database: 5-bank asset concentration", WBI + "GFDD.OI.06"),
      S("Thinking Ahead Institute, The world's largest 500 asset managers (2025)", TAIU), S("Global Custodian, A new era of custody (2025)", GC)],
 steps=[
  st("November 2025", "The whole world", WORLD, 1.15, "Twenty-Nine Banks Too Large to Fail",
   "Each November the Financial Stability Board publishes the banks whose failure, in its judgement, would endanger the whole system. The 2025 list has 29 names, the same as the year before. Eight are American, five Chinese, four French, three Japanese, three British, two Canadian, and one each is German, Swiss, Dutch and Spanish. All 29 are drawn. Being on the list means a bank must hold somewhat more capital. It also tells every lender that this bank's government will not let it go under. Lenders charge such a bank less, because the risk has been moved to the public. So the list meant to restrain the largest banks also hands them cheaper funding than any smaller rival can get, and helps them grow larger.",
   GSIB, w=1, pl=["jpm", "citi", "bofa", "gs", "ms", "wfc", "bny", "statestreet", "icbc", "abc", "boc", "ccb", "bocom", "bnp", "ca", "bpce", "socgen", "mufg", "smfg", "mizuho", "hsbc", "barclays", "stanchart", "rbc", "td", "deutsche", "ubs", "ing", "santander"],
   add={"United States": 0, "China": 0, "France": 0, "Japan": 0, "United Kingdom": 0, "Canada": 0, "Germany": 0, "Switzerland": 0, "Netherlands": 0, "Spain": 0},
   note="Every ringed circle is one of the 29 banks on the Financial Stability Board's 2025 list, at its headquarters. All 29 are drawn; nothing is left out. The shaded countries are their ten home countries."),
  st("2021", "Every country with a figure", WORLD, 1.15, "Inside Most Countries, Five Banks Hold Most of the Assets",
   "The world list hides how concentrated banking is at home. The World Bank publishes, for each country, the share of all commercial bank assets held by the five largest banks. Among the %(conc5_n)s countries with a figure, the five largest hold three quarters or more in %(conc5_75)s, and nine tenths or more in %(conc5_90)s. For the customer this sets the terms of everything in Chapter 2: the rate paid on savings, the rate charged on loans, the fees. Five banks do not need to agree anything in order to charge alike; each can see what the others do. For the government it means that any one of the five is too large to fail in that country, whether or not it appears on a world list.",
   WBI + "GFDD.OI.06", data={"k": "conc5"}),
  st("End of 2024", "New York, Malvern, Boston", [-74.5, 41], 4.6, "Twenty Managers Hold Nearly Half the Managed Money",
   "The savings that leave banks do not spread out. Of the 139.9 trillion dollars run by the 500 largest asset managers at the end of 2024, the top 20 ran 65.8 trillion, or 47 per cent, up from 45.5 per cent a year before. Fifteen of the 20 are American. BlackRock and Vanguard alone ran 21.7 trillion. Because index funds buy every company on the list, the largest managers end up among the largest shareholders of almost every listed company at once, including companies that compete with each other and including the banks and exchanges in this chapter. The managers also cast the votes attached to those shares. The pension savers whose money it is are not asked.",
   TAIU, pl=["blackrock", "vanguard", "fidelity", "statestreet", "jpm", "gs", "capital", "amundi", "ubs", "invesco", "troweprice", "franklin", "pimco"], ex=["tai2025"], add={"United States": 0}),
  st("Today", "New York", NY, 3.0, "One Firm in Every Role",
   "Take JPMorgan Chase and walk back through the map. Chapter 2: it is the largest bank in the United States. Chapter 3: an investment bank, one of the four custodians that together hold 180 trillion dollars, and the fifth-largest asset manager with 4.0 trillion. Chapter 5: a dollar correspondent for banks abroad and an owner of CHIPS. Chapter 6: an owner and user of the depository and a member of the clearing houses. Chapter 7: a clearing bank and lender in repo. Chapter 9: a member of the associations that draft the rules. The same is true, with small differences, of a dozen others. A firm in all those positions sees its customers' orders, holds their collateral, lends to their rivals and advises their targets, and relies on internal walls to keep each arm from using what the others know.",
   GC, pl=["jpm", "tch", "dtcc", "lch", "cme", "isda", "iif"], ex=["custody2025"], add={"United States": 0}),
 ])

# ================================================================== PART 4 · THE BILL
flow(id="toll", part=3, scope="world",
 title="The Toll",
 kick="Moving savings to borrowers costs about two cents a year on every dollar handled. It cost about the same in 1900, before computers.",
 sum="Part 3 showed who runs the system. Part 4 asks what the rest of us pay for it and what we carry when it goes wrong. Start with the price.<br><br>Every firm on this map is paid by a spread or a fee, as the first slide said. Add all of them together, across a whole country and a whole year, and you have what that country pays its financial system. An economist at New York University, Thomas Philippon, did the sum for the United States for every year since the 1880s, and set it against the amount of saving and borrowing the system actually handled.<br><br>I use the word toll for this because it is charged for passing through, and because most of it is never shown to the person paying. It is inside the gap between the interest rate on a loan and the rate on a deposit, inside the price of a pension fund's units, inside the price of anything bought from a shop that takes cards.",
 bridge="The four slides find the toll in four places. The first is the total, measured over 130 years. The second maps the gap between lending and deposit rates. The third works out what a yearly fee does to forty years of saving. The fourth maps what it costs a migrant worker to send wages home.",
 out="The toll is about 2 per cent a year on everything handled, it has not fallen in a century, and it is highest for those with the least. The next chapter turns from the price to the risk.",
 rec="The system charges about 2 per cent a year on what it handles, no less than a century ago, and charges the poorest the most.",
 roles=[],
 src=[S("Thomas Philippon, Has the US Finance Industry Become Less Efficient? (NBER Working Paper 18077; American Economic Review, 2015)", PHIL),
      S("Thomas Philippon, Has the finance industry become less efficient? (VoxEU)", PHILV),
      S("World Bank, Interest rate spread (lending rate minus deposit rate)", WBI + "FR.INR.LNDP"),
      S("World Bank, Average transaction cost of sending remittances to a specific country", WBI + "SI.RMT.COST.IB.ZS")],
 steps=[
  st("1880s to 2010s", "New York", NY, 3.0, "Two Per Cent, for 130 Years",
   "Philippon added up everything Americans paid to financial firms each year, all the spreads and all the fees, and divided it by the amount of lending, investing and safekeeping those firms did. He found the cost was around 2 per cent of the assets handled, every year, and that it stayed between 1.3 and 2.3 per cent across 130 years. It did not fall when the telephone arrived, or the computer, or the internet. In the same period the cost of selling goods in shops fell steeply. As a share of the whole economy, he found, finance took about 2 per cent in 1870, under 4 per cent in 1950, 5 per cent in 1980 and almost 9 per cent in 2010. His explanation is that the savings from technology were spent on more trading and kept as higher pay and profit, and were not passed to customers.",
   PHIL, ex=["philippon"], add={}),
  st("Latest year", "Every country with a figure", WORLD, 1.15, "The Gap Between What Banks Charge and What They Pay",
   "The plainest part of the toll is the spread from the very first slide: the interest rate a bank charges borrowers minus the rate it pays depositors. The World Bank publishes it for %(spread_n)s countries. In %(spread_hi)s of them the gap is 8 percentage points or more. Those are mostly poorer countries, where a few banks face little competition and lend mainly to the government and large firms. A farmer or shopkeeper there who can get a bank loan at all pays several times what a business in Germany or Japan pays, and earns almost nothing on savings. Part of the gap covers real losses from loans that are not repaid. The rest is what the bank keeps. Chapter 12 showed how few banks most countries have.",
   WBI + "FR.INR.LNDP", data={"k": "spread"}),
  st("Today", "The whole world", WORLD, 1.15, "What a Small Yearly Fee Does Over a Working Life",
   "Fees on savings are quoted as small yearly percentages, which hides their effect. Take a worker who saves 200 a month for 40 years, and suppose investments grow 5 per cent a year. With no fees she ends with about %(fee_none)s. Now take 1.5 per cent a year off for the chain of firms in Chapter 8: the manager, the platform, the adviser, the trading costs. She ends with about %(fee_some)s. The difference, about %(fee_gap)s, is %(fee_pct)s per cent of what she would have had. She paid in the same amount in both cases, and bore all the risk of the investments in both. A fee charged on the whole pile every year takes a slice of all the earlier growth as well as of this year's savings. An index fund can cost a tenth of that, so the kind of fund a worker is placed in by default matters more than almost any other choice.",
   PHILV, w=1, note="This slide shades no country. The saver and her numbers are arithmetic I wrote to show the rule; they describe no real fund."),
  st("2023", "Every country with a figure", WORLD, 1.15, "Sending Wages Home",
   "The highest toll is paid on some of the smallest payments. A migrant worker sending 200 dollars to family passes through the chain in Chapter 5: a transfer company or bank, a correspondent, a currency exchange and a paying agent. The World Bank records the average cost of sending money to %(remcost_n)s countries. To %(remcost_hi)s of them it is 6 per cent or more, twice the 3 per cent the world's governments set as a target for 2030 in the Sustainable Development Goals. On 200 dollars, 6 per cent is 12 dollars, a day's food for a family in many of the receiving countries. The cost is highest where few firms serve the route and where banks have closed the accounts of transfer companies. Where a phone-based system reaches both ends, it falls to a fraction.",
   WBI + "SI.RMT.COST.IB.ZS", data={"k": "remcost"}, pl=[]),
 ])

flow(id="breaks", part=3, scope="world",
 title="When It Breaks",
 kick="Every promise in Chapter 2 can fail. When one does, the loss has to land on someone, and the order in which people are protected is not the order most customers assume.",
 sum="A system that holds other people's money on thin capital, funds itself overnight and routes everything through a few firms will sometimes break. Since 1970 it has done so in most countries on earth, some several times.<br><br>When a financial firm fails, the loss is real and someone bears it. There is a queue. The owners are meant to lose first, then those who lent the firm money, then large depositors, with small depositors protected by insurance. That is the order on paper. In practice, when the firm is one of the few dozen at the centre, governments have stepped in before the queue was followed, because letting the loss fall where the rules said would have stopped the pipes for everyone.<br><br>The result is an arrangement in which the gains of the good years belong to owners and staff, and the largest losses of the bad years are taken by the public. Each firm at the centre can borrow more cheaply because of it.",
 bridge="The four slides move from a single bank to the whole system. The first is the run on an American bank in 2023 and what happened to the insurance limit. The second is the forced sale of a Swiss bank the same month. The third maps banking crises in every country since 1970. The fourth looks at what stands behind a clearing house.",
 out="When a firm at the centre fails, the written order of losses gives way and public money or a public guarantee fills the gap. The last chapter with slides looks at who is outside the system altogether.",
 rec="When a central firm fails, governments step in ahead of the rules, so the largest losses fall on the public.",
 roles=["Where the failed bank was based"],
 src=[S("Federal Deposit Insurance Corporation, joint statement by Treasury, Federal Reserve and FDIC, 12 March 2023", FDICSVB), S("Wikipedia, Collapse of Silicon Valley Bank", SVBW),
      S("Wikipedia, Acquisition of Credit Suisse by UBS", CSW), S("Laeven and Valencia, Systemic Banking Crises Database (International Monetary Fund)", LV), S("Wikipedia, Central counterparty clearing", CCPW)],
 steps=[
  st("March 2023", "Santa Clara, California", SANTACLARA, 4.2, "Regional Example: A Run in a Day, and the Limit That Did Not Apply",
   "Regional Example: Silicon Valley Bank, United States, 2023. The bank had taken deposits from technology companies and put much of the money into long-dated government bonds. When interest rates rose the bonds fell in price, as in Chapter 7. Depositors heard, and tried to withdraw tens of billions of dollars within a day, by phone. The bank was closed on 10 March 2023. Deposit insurance covered 250,000 dollars per customer, and by the bank's own regulatory reports about 89 per cent of its deposits were above that limit. Two days later the Treasury, the Federal Reserve and the deposit insurer announced that all depositors would be fully protected, using an exception for risks to the whole system. So the limit holds for a small bank's customers and was waived for this one. The cost falls on a fund paid for by all banks, and in the end by their customers.",
   FDICSVB, reg=True, add={"United States": 0}, ex=["svb"], pl=["fdic"]),
  st("19 March 2023", "Zurich", ZURICH, 4.0, "Regional Example: A Designated Bank, Sold Over a Weekend",
   "Regional Example: Credit Suisse, Switzerland, 2023. Credit Suisse was one of the banks on the too-large-to-fail list, which meant it had filed plans for an orderly wind-down that would spare the public. When customers began pulling money out in March 2023 the plans were not used. Over one weekend the Swiss government arranged its sale to its only large rival, UBS, for 3 billion francs. The central bank offered more than 100 billion francs of liquidity, and the government guaranteed UBS against up to 9 billion francs of losses. Bonds worth 16 billion francs, sold to investors as loss-absorbing, were written down to zero, while shareholders, who should have lost first, received UBS shares. Switzerland now has one large bank where it had two, with a balance sheet larger than the country's economy.",
   CSW, reg=True, add={"Switzerland": 0}, ex=["creditsuisse"], pl=["ubs", "finma"]),
  st("1970 to 2025", "Every country", WORLD, 1.15, "Banking Crises, Country by Country",
   "These two were not exceptions. Two economists at the International Monetary Fund, Laeven and Valencia, keep a list of every systemic banking crisis since 1970: episodes in which a country's banks suffered runs or losses severe enough to force major government intervention. Leaving aside the cases they mark as borderline, their list has %(crises_total)s crises in %(crises_n)s countries, and %(crises_multi)s countries have had more than one. The map shades every country by its number. A banking crisis is paid for three times: by taxpayers who fund the rescue, by workers who lose jobs in the recession that follows, and by savers whose deposits or pensions shrink. The people who ran the banks kept what they had been paid in the years before.",
   LV, data={"k": "crises"}),
  st("Today", "London, Chicago, Frankfurt", [-40, 46], 2.1, "What Stands Behind a Clearing House",
   "Chapter 6 said that clearing collects risk into one place. If a member of a clearing house fails owing more than the margin it posted, the loss is covered in a set order: the failed member's own contribution to the shared fund, then a slice of the clearing house's own money, then the contributions of all the other members, then further calls on those members for cash. The members are the 29 banks of Chapter 12 and a few others. So a failure large enough to exhaust the fund would arrive at the largest banks on the same day, as a demand for cash, at the moment markets were already falling. No clearing house of the largest size has yet failed. The authorities list several as critical to the system, which is the wording once used for the banks.",
   CCPW, pl=["lch", "cme", "eurexclearing", "iceclearcredit", "occ", "jscc", "dtcc"], ex=["fsoc8"], arcs=[[CHICAGO, LONDON], [LONDON, FRANKFURT]], an=[["Chicago", "London"], ["London", "Frankfurt"]]),
 ])

flow(id="outside", part=3, scope="world",
 title="Who Is Left Outside",
 kick="For all its size, the system does not serve everyone. More than a billion adults have no account, and whole countries are losing their links to the pipes.",
 sum="The last question is who the system does not reach. Chapter 1 gave it four jobs: moving money, keeping it safe, lending and spreading risk. For a large part of the world's people it does none of them.<br><br>Being outside is expensive. Without an account, wages are paid in cash and can be stolen. Savings are kept in animals, jewellery or under a mattress and earn nothing. Borrowing means a moneylender. There is no insurance, so one illness can cost a family its land.<br><br>The firms at the centre have no reason to change this. A customer with a small balance costs a bank about as much to serve as one with a large balance and earns it far less. And since the rules against money laundering make a bank answerable for its customers, the cheapest way to comply is to stop serving anyone small, poor or far away.",
 bridge="The two slides look at people and then at countries. The first maps the share of adults with any account. The second shows banks in small and poor countries losing their correspondent links.",
 out="More than a billion adults and a growing number of small countries stand outside the system or at its edge. The final chapter puts the whole machine in one view.",
 rec="More than a billion adults have no account, and small countries are losing their links to the international pipes.",
 roles=[],
 src=[S("World Bank, Global Findex 2025 press release", FINDEX), S("World Bank, Account ownership (per cent of adults)", WBI + "FX.OWN.TOTL.ZS"),
      S("Bank for International Settlements, CPMI correspondent banking data", CPMIC)],
 steps=[
  st("2024", "Every country with a figure", WORLD, 1.15, "Adults With an Account",
   "The World Bank surveys adults in most countries about whether they have an account at a bank or with a mobile money service. In its 2025 report 79 per cent of the world's adults had one, up from 51 per cent in 2011. That leaves 1.3 billion without. More than half of them, about 650 million, live in eight countries: Bangladesh, China, Egypt, India, Indonesia, Mexico, Nigeria and Pakistan. The map shades each country by the share of adults with an account, darkest where fewest have one; in %(acct_40)s of %(acct_n)s countries it is under 40 per cent. Most of the rise since 2011 came from mobile phones. In much of Africa a phone company, and not a bank, brought people in, after decades in which banks had not.",
   WBI + "FX.OWN.TOTL.ZS", data={"k": "acct"}, ex=["findex2025"]),
  st("Today", "The whole world", WORLD, 1.15, "Countries Losing Their Links",
   "Chapter 5 showed that a country's banks reach the dollar, the euro and the pound through a correspondent bank in New York, Frankfurt or London. The Bank for International Settlements tracks these links from Swift's message records, and describes the network as reportedly shrinking and becoming more concentrated. A large bank earns little from a small bank in a small country and risks a fine if one of that bank's customers turns out to be a criminal, so it closes the account. Small island states and poor countries lose the most links. When the last link goes, importers there cannot pay suppliers, families cannot receive wages sent from abroad through a bank, and aid agencies carry cash. Nothing in the system obliges any bank to keep the link open. The task force in Paris from Chapter 9 sets the checks, and a private bank makes the decision.",
   CPMIC, w=1, pl=["cpmi", "fatf", "citi", "jpm", "stanchart", "hsbc", "deutsche", "westernunion", "wise"], ex=["cpmi_corr"], note="This slide shades no country, because the Bank for International Settlements publishes these figures by region and corridor and I have not placed them by country here. The ringed circles are the two standard-setting bodies named in the text, five large correspondent banks and two money transfer companies."),
 ])

flow(id="whole", part=3, scope="world",
 title="The Whole Machine",
 kick="Every chapter in one view, from the committees that write the rules to the worker whose pension pays the fees.",
 sum="Put the chapters end to end.<br><br>A financial system does four jobs with money that belongs to its customers: it moves it, keeps it, lends it on and spreads risk. Banks, insurers and pension funds take the money in. Asset managers, investment banks, brokers, exchanges, custodians, private funds, rating agencies and auditors work in the middle, each for a fee or a spread. Regulators watch, many of them funded by the firms they watch.<br><br>A payment is a message and a settlement. Inside a country it settles on the central bank's books. Across borders it rides a chain of correspondent banks and, for most of the world, settles in New York. A share is traded on a market that is a company, guaranteed by a clearing house that is usually owned by that company, and recorded at a single depository in a nominee's name. The firms that do this fund themselves overnight against collateral, and a fall in the collateral's price sends all of them looking for cash at once. Most of the lending that results goes to property, and to other financial firms.<br><br>The rules are drafted by committees in Basel and by private associations before any parliament sees them. Three agencies rate nearly every bond and four networks audit nearly every large company, paid by those they judge. Each pipe has one or two owners, who can disconnect a bank or a country. Twenty-nine banks, four custodians and twenty asset managers sit at the centre, and many are the same firms.<br><br>For this the system charges about 2 per cent a year of everything it handles, as it did in 1900, and more to a farmer in a poor country or a migrant sending wages home. When a firm at the centre fails, governments have covered the loss ahead of the written rules. More than a billion adults are outside the system altogether.<br><br>None of this is hidden. Every figure above comes from a regulator, a central bank, the firms' own reports or published research, and each chapter names its sources. It is simply described, when it is described at all, in words most people were never taught. The first eight chapters of this map were an attempt to teach them.",
 bridge="The one slide draws the bodies that the official lists and published rankings in this map place at the centre: the 29 designated banks, the eight market utilities the United States has designated, the two international depositories, the message network, the three large rating agencies, the four audit networks and the three largest asset managers.",
 out="From here, open any organisation, country or record, or go back to any chapter.",
 rec="",
 roles=[],
 src=[S("Financial Stability Board, 2025 list of global systemically important banks", GSIB), S("US Financial Stability Oversight Council, designations", FSOC),
      S("US Securities and Exchange Commission, staff report on rating organisations (January 2025)", SECR), S("Thinking Ahead Institute, The world's largest 500 asset managers (2025)", TAIU)],
 steps=[
  st("Today", "New York to Frankfurt", [-36, 44], 1.9, "The Bodies the System Runs Through",
   "This last slide draws only what official lists and published rankings put at the centre. The 29 banks the Financial Stability Board names as too large to fail. The market utilities the United States has designated as critical: the company behind CHIPS, the currency settlement bank CLS, the Chicago Mercantile Exchange, the depository and two clearing arms of DTCC, ICE Clear Credit and the Options Clearing Corporation. The two international depositories, Euroclear and Clearstream, and LCH. Swift. The three agencies with 94 per cent of ratings and the four audit networks. The three largest asset managers. About fifty organisations, most of them in New York, London and a few other cities. A payment, a pension or a government bond anywhere in the world passes through several of them. The legend lets you switch each kind on and off and see them on their own.",
   GSIB, w=0,
   pl=["jpm", "citi", "bofa", "gs", "ms", "wfc", "bny", "statestreet", "icbc", "abc", "boc", "ccb", "bocom", "bnp", "ca", "bpce", "socgen", "mufg", "smfg", "mizuho", "hsbc", "barclays", "stanchart", "rbc", "td", "deutsche", "ubs", "ing", "santander",
       "tch", "cls", "cme", "dtcc", "iceclearcredit", "occ", "euroclear", "clearstream", "lch", "swift", "sp", "moodys", "fitch", "deloitte", "pwc", "ey", "kpmg", "blackrock", "vanguard", "fidelity"],
   ex=["fsoc8"], top=True, note="Every ringed circle is a body named on one of four published lists or rankings: the Financial Stability Board's 29 banks, the United States list of designated market utilities, the rating agencies' shares reported by the United States markets regulator, and the ranking of asset managers. Euroclear, Clearstream, LCH, Swift and the four audit networks are added because earlier chapters give a measured share for each. The view faces the North Atlantic, where most of them are; the Chinese and Japanese banks are on the far side of the globe and appear in the flat view. Being drawn here says a body is central, not that it has done anything wrong."),
 ])
